26	export default async function RekonsiliasiPage({
27	  params,
28	  searchParams,
29	}: {
30	  params: Promise<{ businessId: string }>;
31	  searchParams: Promise<{ account?: string; date?: string }>;
32	}) {
33	  const { businessId } = await params;
34	  const { account: accountParam, date } = await searchParams;
35	  const asOfDate = /^\d{4}-\d{2}-\d{2}$/.test(date ?? "")
36	    ? (date as string)
37	    : new Date().toISOString().slice(0, 10);
38	  const asOfIso = `${asOfDate}T23:59:59+07:00`;
39	
40	  const supabase = await createClient();
41	
42	  const { data: business } = await supabase
43	    .from("businesses")
44	    .select("id, name")
45	    .eq("id", businessId)
46	    .single();
47	
48	  if (!business) {
49	    notFound();
50	  }
51	
52	  const { data: accounts } = await supabase
53	    .from("accounts")
54	    .select("id, code, name, normal_balance")
55	    .eq("business_id", businessId)
56	    .eq("type", "aset")
57	    .order("code", { ascending: true });
58	
59	  if (!accounts || accounts.length === 0) {
60	    notFound();
61	  }
62	
63	  const selectedAccount =
64	    accounts.find((a) => a.id === accountParam) ?? accounts[0];
65	
66	  const { data: entries } = await supabase
67	    .from("journal_entries")
68	    .select("journal_lines(debit, credit, account_id)")
69	    .eq("business_id", businessId)
70	    .lte("date", asOfIso);
71	
72	  let raw = 0;
73	  for (const entry of entries ?? []) {
74	    const lines = entry.journal_lines as unknown as {
75	      debit: number;
76	      credit: number;
77	      account_id: string;
78	    }[];
79	    for (const l of lines) {
80	      if (l.account_id === selectedAccount.id) {
81	        raw += Number(l.debit) - Number(l.credit);
82	      }
83	    }
84	  }
85	  const bookBalance = selectedAccount.normal_balance === "debit" ? raw : -raw;
86	
87	  const { data: history } = await supabase
88	    .from("account_reconciliations")
89	    .select("id, statement_date, book_balance, statement_balance, difference, note")
90	    .eq("business_id", businessId)
91	    .eq("account_id", selectedAccount.id)
92	    .order("statement_date", { ascending: false })
93	    .limit(10);
94	
95	  const lastRecon = history?.[0];
96	  const windowFromDate = lastRecon ? addDays(lastRecon.statement_date, 1) : addDays(asOfDate, -30);
97	  const windowFromIso = `${windowFromDate}T00:00:00+07:00`;
98	
99	  const { data: windowEntries } = await supabase
100	    .from("journal_entries")
101	    .select("date, description, journal_lines(debit, credit, account_id)")
102	    .eq("business_id", businessId)
103	    .gte("date", windowFromIso)
104	    .lte("date", asOfIso)
105	    .order("date", { ascending: false });
106	
107	  const mutations = (windowEntries ?? []).flatMap((e) => {
108	    const lines = e.journal_lines as unknown as {
109	      debit: number;
110	      credit: number;
111	      account_id: string;
112	    }[];
113	    return lines
114	      .filter((l) => l.account_id === selectedAccount.id)
115	      .map((l) => ({ date: e.date, description: e.description, debit: Number(l.debit), credit: Number(l.credit) }));
116	  });
117	
118	  const boundAddReconciliation = addAccountReconciliation.bind(null, businessId);
119	  const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });
120	
121	  return (
122	    <div className="w-full max-w-2xl">
123	      <div className="flex flex-wrap items-center justify-between gap-2">
124	        <div>
125	          <h1 className="text-lg font-bold text-zinc-900">Rekonsiliasi Rekening — {business.name}</h1>
126	          <p className="mt-0.5 text-xs text-zinc-500">
127	            Bandingkan saldo menurut jurnal dengan saldo rekening koran/kas fisik.
128	          </p>
129	        </div>
130	        <form method="get" className="flex flex-wrap items-center gap-2">
131	          <select
132	            name="account"
133	            defaultValue={selectedAccount.id}
134	            className="rounded-lg border border-zinc-200 px-2.5 py-1.5 text-xs"
135	          >
136	            {accounts.map((a) => (
137	              <option key={a.id} value={a.id}>
138	                {a.code} — {a.name}
139	              </option>
140	            ))}
141	          </select>
142	          <input
143	            type="date"
144	            name="date"
145	            defaultValue={asOfDate}
146	            className="rounded-lg border border-zinc-200 px-2.5 py-1.5 text-xs"
147	          />
148	          <button
149	            type="submit"
150	            className="rounded-lg bg-brand-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-700"
151	          >
152	            Tampilkan
153	          </button>
154	        </form>
155	      </div>
156	
157	      <div className="mt-6 rounded-2xl border border-zinc-200 bg-white p-5">
158	        <p className="text-xs text-zinc-500">Saldo Menurut Jurnal per {asOfDate}</p>
159	        <p className="mt-1 text-2xl font-bold text-zinc-900">{formatRupiah(bookBalance)}</p>
160	      </div>
161	
162	      <div className="mt-4 rounded-2xl border border-zinc-200 bg-white p-5">
163	        <h2 className="mb-4 text-sm font-semibold text-zinc-900">Catat Rekonsiliasi</h2>
164	        <ReconciliationForm
165	          action={boundAddReconciliation}
166	          today={today}
167	          accounts={accounts}
168	          selectedAccountId={selectedAccount.id}
169	        />
170	      </div>
171	
172	      <div className="mt-4 overflow-hidden rounded-2xl border border-zinc-200 bg-white">
173	        <div className="border-b border-zinc-100 px-4 py-3">
174	          <h2 className="text-sm font-bold text-zinc-900">
175	            Mutasi {selectedAccount.name} sejak{" "}
176	            {lastRecon ? `rekonsiliasi terakhir (${formatDate(lastRecon.statement_date)})` : `30 hari sebelum ${asOfDate}`}
177	          </h2>
178	          <p className="mt-0.5 text-[11px] text-zinc-400">
179	            Cek daftar ini kalau ada selisih — biasanya karena transfer/setoran yang belum settle di
180	            bank.
181	          </p>
182	        </div>
183	        <div className="divide-y divide-zinc-50 px-4">
184	          {mutations.length === 0 && (
185	            <p className="py-6 text-center text-xs text-zinc-300">Tidak ada mutasi di rentang ini.</p>
186	          )}
187	          {mutations.map((m, i) => (
188	            <div key={i} className="flex items-center justify-between gap-2 py-2 text-xs">
189	              <div className="min-w-0">
190	                <p className="truncate text-zinc-700">{m.description}</p>
191	                <p className="text-[11px] text-zinc-400">{formatDate(m.date)}</p>
192	              </div>
193	              <span className="shrink-0 font-medium text-zinc-800">
194	                {m.debit > 0 ? formatRupiah(m.debit) : `(${formatRupiah(m.credit)})`}
195	              </span>
196	            </div>
197	          ))}
198	        </div>
199	      </div>
200	
201	      <div className="mt-4 overflow-hidden rounded-2xl border border-zinc-200 bg-white">
202	        <div className="border-b border-zinc-100 px-4 py-3">
203	          <h2 className="text-sm font-bold text-zinc-900">Riwayat Rekonsiliasi</h2>
204	        </div>
205	        <div className="divide-y divide-zinc-50 px-4">
206	          {(history ?? []).length === 0 && (
207	            <p className="py-6 text-center text-xs text-zinc-300">Belum ada rekonsiliasi tersimpan.</p>
208	          )}
209	          {(history ?? []).map((h) => (
210	            <div key={h.id} className="py-2.5 text-xs">
211	              <div className="flex items-center justify-between">
212	                <span className="font-medium text-zinc-700">{formatDate(h.statement_date)}</span>
213	                <span
214	                  className={
215	                    Math.abs(Number(h.difference)) < 1
216	                      ? "font-semibold text-brand-700"
217	                      : "font-semibold text-red-600"
218	                  }
219	                >
220	                  {Math.abs(Number(h.difference)) < 1 ? "✓ Cocok" : `Selisih ${formatRupiah(Number(h.difference))}`}
221	                </span>
222	              </div>
223	              <div className="mt-0.5 flex items-center justify-between text-[11px] text-zinc-400">
224	                <span>
225	                  Buku {formatRupiah(Number(h.book_balance))} vs Bank {formatRupiah(Number(h.statement_balance))}
226	                </span>
227	              </div>
228	              {h.note && <p className="mt-0.5 text-[11px] text-zinc-400">{h.note}</p>}
229	            </div>
230	          ))}
231	        </div>
232	      </div>
233	
234	      <p className="mt-3 text-center text-[11px] text-zinc-400">
235	        Alat ini tidak mengubah jurnal — cuma mencatat perbandingan saldo sebagai riwayat. Kalau
236	        ketemu selisih yang perlu dikoreksi, tambahkan lewat{" "}
237	        <Link href={`/business/${businessId}/accounting/jurnal`} className="text-brand-600 hover:underline">
238	          Jurnal Manual
239	        </Link>
240	        .
241	      </p>
242	    </div>
243	  );
244	}
