156	                <span>− {a.label}</span>
157	                <span className="flex items-center gap-1.5">
158	                  {formatRupiah(Number(a.amount))}
159	                  {!isPaid && (
160	                    <span className="print:hidden">
161	                      <DeleteAdjustmentButton
162	                        businessId={businessId}
163	                        payslipId={payslipId}
164	                        adjustmentId={a.id}
165	                      />
166	                    </span>
167	                  )}
168	                </span>
169	              </div>
170	            ))}
171	            <div className="flex justify-between border-t border-dashed border-zinc-300 pt-2 text-base font-bold text-zinc-900">
172	              <span>Total Diterima</span>
173	              <span>{formatRupiah(totalDiterima)}</span>
174	            </div>
175	            {isPaid && (
176	              <p className="text-right text-xs font-medium text-brand-600">
177	                ✓ Dibayar {formatDate(payslip.paid_at!.slice(0, 10))}
178	              </p>
179	            )}
180	          </div>
181	        </div>
182	
183	        <div className="mt-4 print:hidden">
184	          {isPaid ? (
185	            <div className="rounded-xl border border-brand-200 bg-brand-50 p-3 text-center text-xs font-medium text-brand-700">
186	              ✓ Slip ini sudah dibayar dan tercatat di jurnal (Beban Gaji / Kas &amp; Bank).
187	            </div>
188	          ) : (
189	            <div className="space-y-3">
190	              <LemburThrForm
191	                action={boundUpdateExtras}
192	                initialLembur={lemburAmount}
193	                initialThr={thrAmount}
194	              />
195	              <AddAdjustmentForm action={boundAddAdjustment} />
196	              <MarkPaidButton action={boundMarkPaid} totalDiterima={totalDiterima} />
197	            </div>
198	          )}
199	        </div>
200	    </div>
201	  );
202	}
