8	export async function addAccountReconciliation(
9	  businessId: string,
10	  prevState: AddReconciliationState,
11	  formData: FormData,
12	): Promise<AddReconciliationState> {
13	  const fail = (msg: string): AddReconciliationState => ({
14	    error: msg,
15	    resetToken: prevState.resetToken,
16	  });
17	
18	  const accountId = formData.get("accountId") as string;
19	  const statementDate = formData.get("statementDate") as string;
20	  const statementBalanceRaw = formData.get("statementBalance") as string;
