19	// Kalkulator HPP Desktop — pesanan sekali-beli tanpa akun/business_id sama
20	// sekali (lihat 20260713130000_hpp_desktop_orders.sql). Order ID-nya diberi
21	// prefix "HPP-" (dibuat di kalkulator-hpp/beli/actions.ts) supaya bisa
22	// dibedakan dari order langganan bisnis ("KK-...") di webhook yang sama —
23	// Midtrans hanya punya satu URL notifikasi per akun, jadi ini tidak bisa
24	// dipecah jadi route terpisah.
25	async function handleDesktopOrderNotification(
26	  supabase: ReturnType<typeof createServiceClient>,
27	  body: MidtransNotification,
28	) {
29	  const { data: order } = await supabase
30	    .from("hpp_desktop_orders")
31	    .select("id, status")
32	    .eq("order_id", body.order_id)
33	    .maybeSingle();
34	
35	  if (!order) {
36	    console.error(`Midtrans notification for unknown hpp_desktop_orders order_id: ${body.order_id}`);
37	    return NextResponse.json({ ok: true });
38	  }
39	
40	  if (order.status === "settlement") {
41	    // Sudah diproses — Midtrans mengulang notifikasi, ini normal.
42	    return NextResponse.json({ ok: true });
43	  }
44	
45	  const newStatus = SETTLED_STATUSES.has(body.transaction_status)
46	    ? "settlement"
47	    : FAILED_STATUSES.has(body.transaction_status)
48	      ? body.transaction_status
49	      : "pending";
50	
51	  await supabase
52	    .from("hpp_desktop_orders")
53	    .update({
54	      status: newStatus,
55	      midtrans_transaction_id: body.transaction_id ?? null,
56	      payment_type: body.payment_type ?? null,
57	      raw_notification: body,
58	      ...(newStatus === "settlement" ? { download_token: randomUUID() } : {}),
59	    })
60	    .eq("id", order.id);
61	
62	  return NextResponse.json({ ok: true });
63	}
