1	"use server";
2	
3	import { headers } from "next/headers";
4	import { createClient } from "@/lib/supabase/server";
5	import { getPlan } from "@/lib/billing/plans";
6	
7	const MIDTRANS_BASE_URL = process.env.MIDTRANS_IS_PRODUCTION === "true"
8	  ? "https://app.midtrans.com/snap/v1/transactions"
9	  : "https://app.sandbox.midtrans.com/snap/v1/transactions";
10	
11	export type CreatePaymentResult = { error: string | null; redirectUrl: string | null };
12	
13	export async function createPayment(
14	  businessId: string,
15	  planCode: string,
16	): Promise<CreatePaymentResult> {
17	  const plan = getPlan(planCode);
18	  if (!plan) {
19	    return { error: "Paket tidak ditemukan.", redirectUrl: null };
20	  }
21	
22	  const supabase = await createClient();
23	
24	  const { data: userData } = await supabase.auth.getUser();
25	  if (!userData.user) {
26	    return { error: "Sesi login tidak ditemukan, silakan login ulang.", redirectUrl: null };
27	  }
28	
29	  const { data: business } = await supabase
30	    .from("businesses")
31	    .select("id, name")
32	    .eq("id", businessId)
33	    .single();
34	
35	  if (!business) {
36	    return { error: "Bisnis tidak ditemukan.", redirectUrl: null };
37	  }
38	
39	  const orderId = `KK-${businessId.slice(0, 8)}-${Date.now()}`;
40	
41	  const { error: insertError } = await supabase.from("payments").insert({
42	    business_id: businessId,
43	    plan_code: plan.code,
44	    order_id: orderId,
45	    amount: plan.price,
46	    status: "pending",
47	  });
48	
49	  if (insertError) {
50	    return { error: `Gagal mencatat pembayaran: ${insertError.message}`, redirectUrl: null };
51	  }
52	
53	  const serverKey = process.env.MIDTRANS_SERVER_KEY;
54	  if (!serverKey) {
55	    return { error: "Konfigurasi payment gateway belum lengkap.", redirectUrl: null };
56	  }
57	
58	  const auth = Buffer.from(`${serverKey}:`).toString("base64");
59	
60	  // finish callback is cosmetic only (not authoritative — the webhook is),
61	  // so a best-effort origin from request headers is fine here.
62	  const headerList = await headers();
63	  const host = headerList.get("x-forwarded-host") ?? headerList.get("host");
64	  const protocol = headerList.get("x-forwarded-proto") ?? "https";
65	  const origin = host ? `${protocol}://${host}` : "";
66	
67	  const response = await fetch(MIDTRANS_BASE_URL, {
68	    method: "POST",
69	    headers: {
70	      "Content-Type": "application/json",
71	      Accept: "application/json",
72	      Authorization: `Basic ${auth}`,
73	    },
74	    body: JSON.stringify({
75	      transaction_details: {
76	        order_id: orderId,
77	        gross_amount: plan.price,
78	      },
79	      item_details: [
80	        { id: plan.code, name: plan.name, price: plan.price, quantity: 1 },
81	      ],
82	      customer_details: {
83	        email: userData.user.email,
84	        first_name: business.name,
85	      },
86	      callbacks: {
87	        finish: `${origin}/business/${businessId}/billing?status=selesai`,
88	      },
89	    }),
90	  });
91	
92	  if (!response.ok) {
93	    const body = await response.text();
94	    return { error: `Gagal membuat transaksi pembayaran: ${body}`, redirectUrl: null };
95	  }
96	
97	  const json = (await response.json()) as { redirect_url?: string };
98	  if (!json.redirect_url) {
99	    return { error: "Payment gateway tidak mengembalikan link pembayaran.", redirectUrl: null };
100	  }
101	
102	  return { error: null, redirectUrl: json.redirect_url };
103	}
